window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-342bbdafa520e3ec"]={"versions": [{"id": "FIG-342bbdafa520e3ec", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Teilschritts innerhalb der AUTOSAR E2E-Bibliothek (Profile 02). Es beschreibt den Kontrollfluss der internen Hilfsfunktion <code>E2E_P02_process_NoNewOrRepeatedDataCounter</code> im Kontext der E2E-Prüfroutine (<code>E2E_P02Check</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>State</code>: Zeiger auf die E2E-P02-Zustandsstruktur (<code>E2E_P02CheckStateType</code>), welche den Empfängerzustand vorhält.\n</li><li><code>NoNewOrRepeatedDataCounter</code>: Zustandsvariable innerhalb von <code>State</code> (Typ <code>uint8</code>), welche aufeinanderfolgende Zyklen ohne neue bzw. mit wiederholten Daten zählt.\n</li><li>Entscheidungsknoten (Decision Node) zur Prüfung des Zählergrenzwerts (15).\n</li><li>Aktionsknoten (Action Node) zur Inkrementierung von <code>State-&gt;NoNewOrRepeatedDataCounter</code>.\n</li><li>Zusammenführungsknoten (Merge Node) vor dem Aktivitätsendknoten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten nach Eintritt in die Funktion <code>E2E_P02_process_NoNewOrRepeatedDataCounter</code>.\n</li><li>Verzweigung an der Entscheidung: Prüfung der Bedingung <code>State-&gt;NoNewOrRepeatedDataCounter &lt; 15</code>.\n</li><li>Zweig <code>[TRUE]</code>: Inkrementierung der Zustandsvariable via <code>State-&gt;NoNewOrRepeatedDataCounter += 1</code>. Anschließend Übergang zum Zusammenführungsknoten.\n</li><li>Zweig <code>[FALSE]</code>: Bypass der Inkrementierung; direkter Übergang zum Zusammenführungsknoten (Sättigung bei Erreichen des Maximalwerts 15).\n</li><li>Abschluss der Aktivität am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung für den E2E-Prüfschritt bei fehlenden oder duplizierten Daten in Profil 02: Der Zähler <code>NoNewOrRepeatedDataCounter</code> ist bei jedem Aufruf dieses Prüfschritts um 1 zu erhöhen, bis zur oberen Sättigungsgrenze von 15 (Verhinderung eines Überlaufs des 4-Bit-/8-Bit-Zählers).\n</li><li>Entwickler müssen sicherstellen, dass die Bedingung atomar auf dem E2E-Zustandsobjekt ausgeführt wird und der Zählerwert 15 als Sättigungswert fest implementiert ist.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-39cf1d1dc8c6f0c2", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines algorithmischen Teilschritts innerhalb der AUTOSAR E2E-Bibliothek (Profile 02). Es beschreibt den Kontrollfluss der internen Hilfsfunktion <code>E2E_P02_process_NoNewOrRepeatedDataCounter</code> im Kontext der E2E-Prüfroutine (<code>E2E_P02Check</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>State</code>: Zeiger auf die E2E-P02-Zustandsstruktur (<code>E2E_P02CheckStateType</code>), welche den Empfängerzustand vorhält.\n</li><li><code>NoNewOrRepeatedDataCounter</code>: Zustandsvariable innerhalb von <code>State</code> (Typ <code>uint8</code>), welche aufeinanderfolgende Zyklen ohne neue bzw. mit wiederholten Daten zählt.\n</li><li>Entscheidungsknoten (Decision Node) zur Prüfung des Zählergrenzwerts (15).\n</li><li>Aktionsknoten (Action Node) zur Inkrementierung von <code>State-&gt;NoNewOrRepeatedDataCounter</code>.\n</li><li>Zusammenführungsknoten (Merge Node) vor dem Aktivitätsendknoten.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Start am Initialknoten nach Eintritt in die Funktion <code>E2E_P02_process_NoNewOrRepeatedDataCounter</code>.\n</li><li>Verzweigung an der Entscheidung: Prüfung der Bedingung <code>State-&gt;NoNewOrRepeatedDataCounter &lt; 15</code>.\n</li><li>Zweig <code>[TRUE]</code>: Inkrementierung der Zustandsvariable via <code>State-&gt;NoNewOrRepeatedDataCounter += 1</code>. Anschließend Übergang zum Zusammenführungsknoten.\n</li><li>Zweig <code>[FALSE]</code>: Bypass der Inkrementierung; direkter Übergang zum Zusammenführungsknoten (Sättigung bei Erreichen des Maximalwerts 15).\n</li><li>Abschluss der Aktivität am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Festlegung für den E2E-Prüfschritt bei fehlenden oder duplizierten Daten in Profil 02: Der Zähler <code>NoNewOrRepeatedDataCounter</code> ist bei jedem Aufruf dieses Prüfschritts um 1 zu erhöhen, bis zur oberen Sättigungsgrenze von 15 (Verhinderung eines Überlaufs des 4-Bit-/8-Bit-Zählers).\n</li><li>Entwickler müssen sicherstellen, dass die Bedingung atomar auf dem E2E-Zustandsobjekt ausgeführt wird und der Zählerwert 15 als Sättigungswert fest implementiert ist.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-342bbdafa520e3ec", "to": "FIG-39cf1d1dc8c6f0c2", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
